import { MakeLogicType, actions, connect, kea, key, path, props, reducers, selectors } from 'kea'
import { subscriptions } from 'kea-subscriptions'

import { Dayjs, dayjs, now } from 'lib/dayjs'
import { DASHBOARD_MIN_REFRESH_INTERVAL_MINUTES } from 'scenes/dashboard/dashboardUtils'

import { DataNodeStatusMap, dataNodeCollectionLogic } from '~/queries/nodes/DataNode/dataNodeCollectionLogic'

import { homeTabDataCollectionId } from './homeTabQueryKeys'

export interface HomeTabReloadLogicProps {
    teamId: number | null
}

// Generated by kea-typegen. Update if you're an agent, ignore if you're human.
export interface homeTabReloadLogicValues {
    areAnyLoading: boolean // dataNodeCollectionLogic
    collectionNodeStatus: DataNodeStatusMap // dataNodeCollectionLogic
    nextAllowedReload: Dayjs | null
    reloadDisabledReason: string | null
    tickCount: number
}

// Generated by kea-typegen. Update if you're an agent, ignore if you're human.
export interface homeTabReloadLogicActions {
    reloadAll: () => {} // dataNodeCollectionLogic
    tick: () => {
        value: true
    }
}

// Generated by kea-typegen. Update if you're an agent, ignore if you're human.
export interface homeTabReloadLogicMeta {
    key: number | 'none'
    __keaTypeGenInternalSelectorTypes: {
        nextAllowedReload: (collectionNodeStatus: DataNodeStatusMap) => Dayjs | null
        reloadDisabledReason: (
            areAnyLoading: boolean,
            nextAllowedReload: Dayjs | null,
            tickCount: number
        ) => string | null
    }
}

export type homeTabReloadLogicType = MakeLogicType<
    homeTabReloadLogicValues,
    homeTabReloadLogicActions,
    HomeTabReloadLogicProps,
    homeTabReloadLogicMeta
>

/** Blocks a forced reload of the default dashboard until its oldest result is old enough, like dashboard refresh. */
export const homeTabReloadLogic = kea<homeTabReloadLogicType>([
    props({} as HomeTabReloadLogicProps),
    key(({ teamId }) => teamId ?? 'none'),
    path((key) => ['products', 'product_analytics', 'home', 'homeTabReloadLogic', key]),
    connect(({ teamId }: HomeTabReloadLogicProps) => ({
        values: [
            dataNodeCollectionLogic({ key: homeTabDataCollectionId(teamId) }),
            ['collectionNodeStatus', 'areAnyLoading'],
        ],
        actions: [dataNodeCollectionLogic({ key: homeTabDataCollectionId(teamId) }), ['reloadAll']],
    })),
    actions({
        tick: true,
    }),
    reducers({
        // Recomputes the block after the deadline passes, because nothing else changes at that moment.
        tickCount: [0, { tick: (count) => count + 1 }],
    }),
    selectors({
        nextAllowedReload: [
            (s) => [s.collectionNodeStatus],
            (collectionNodeStatus: DataNodeStatusMap): Dayjs | null => {
                // A failed tile has no retry of its own, so Reload must stay available to recover it.
                if (Object.values(collectionNodeStatus).some((status) => status?.hasError)) {
                    return null
                }
                const refreshes = Object.values(collectionNodeStatus)
                    .map((status) => status?.lastRefresh)
                    .filter((lastRefresh): lastRefresh is string => !!lastRefresh)
                    .map((lastRefresh) => dayjs(lastRefresh))
                if (!refreshes.length) {
                    return null
                }
                const oldest = refreshes.reduce((a, b) => (a.isBefore(b) ? a : b))
                return oldest.add(DASHBOARD_MIN_REFRESH_INTERVAL_MINUTES, 'minutes')
            },
        ],
        reloadDisabledReason: [
            (s) => [s.areAnyLoading, s.nextAllowedReload, s.tickCount],
            (areAnyLoading: boolean, nextAllowedReload: Dayjs | null): string | null => {
                if (areAnyLoading) {
                    return 'Loading'
                }
                if (nextAllowedReload?.isAfter(now())) {
                    return `Next reload possible ${nextAllowedReload.fromNow()}`
                }
                return null
            },
        ],
    }),
    subscriptions(({ actions, cache }) => ({
        nextAllowedReload: (nextAllowedReload: Dayjs | null) => {
            if (!nextAllowedReload) {
                cache.disposables.dispose('reloadUnblockTimer')
                return
            }
            cache.disposables.add(() => {
                const timerId = setTimeout(() => actions.tick(), Math.max(0, nextAllowedReload.diff(now())))
                return () => clearTimeout(timerId)
            }, 'reloadUnblockTimer')
        },
    })),
])
